abstract class Report {
  // The template method — the sequence is fixed here, once
  generate(): string {
    let data = this.fetchData();
    data = this.validate(data);
    data = this.sort(data);
    return this.export(data);
  }

  protected fetchData(): Record[] { return fetchFromDb(); }
  protected validate(data: Record[]) { return data.filter(isValid); }
  protected sort(data: Record[]) { return data.sort(byDate); }

  // The only step each subclass must actually implement
  protected abstract export(data: Record[]): string;
}

class CsvReport extends Report {
  protected export(data: Record[]) { return toCsv(data); }
}
class PdfReport extends Report {
  protected export(data: Record[]) { return toPdf(data); }
}
